cy.fixture("testData").then(data => {
  cy.searchProduct(data.searchData.authorSearch);
  cy.url().should("include", "/arama");
  cy.get(_SearchPage.default.productCards).should("have.length.greaterThan", 0);
  cy.get(_SearchPage.default.productList).find(_SearchPage.default.productCards).then($cards => {
    const firstFiveCards = $cards.slice(0, 5);
    cy.wrap(firstFiveCards).each($card => {
      cy.wrap($card).invoke("text").should("match", new RegExp(data.searchData.authorSearch, "i"));
    });
  });
  cy.get(_SearchPage.default.searchInput).should("have.value", "");
});

cy.fixture("testData").then(data => {
  cy.searchProduct(data.searchData.authorSearch);
  cy.url().should("include", "/arama");
  cy.get(_SearchPage.default.productList).find(_SearchPage.default.productCards).then($cards => {
    const firstThreeCards = $cards.slice(0, 3);
    cy.wrap(firstThreeCards).each($card => {
      cy.wrap($card).find(_SearchPage.default.productPrice).should("be.visible");
      cy.wrap($card).realHover();
      cy.wrap($card).find(_SearchPage.default.addToCartButton).should("be.visible");
    });
  });
});

cy.fixture("testData").then(data => {
  cy.intercept("GET", "**/srv/service/filter/get/filters-categories-brands-models*").as("loadFilters");
  cy.searchProduct(data.searchData.authorSearch);
  cy.url().should("include", "/arama");
  cy.wait("@loadFilters");
  cy.get(_SearchPage.default.categoryFilter).should("be.visible");
  cy.get(_SearchPage.default.categoryOptions, {
    timeout: 10000
  }).should("be.visible").first().click();
  cy.url().should("include", "category=");
});

